    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            if g[r,c]!=bgc and (r,c) not in seen:
                col=int(g[r,c]); q=deque([(r,c)]); seen.add((r,c)); cs=set()
                while q:
                    a,b=q.popleft(); cs.add((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<g.shape[0] and 0<=y<g.shape[1] and g[x,y]==col and (x,y) not in seen:
