import numpy as np, re, os
from collections import Counter,deque,defaultdict
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps_of(g,bg):
    H,W=g.shape; lab=np.zeros((H,W),int); n=0
    for r in range(H):
        for c in range(W):
            if g[r,c]!=bg and lab[r,c]==0:
                n+=1; st=[(r,c)]; col=g[r,c]; comp=[]
                while st:
                    p,q=st.pop(); lab[p,q]=n; comp.append((p,q))
                    for dr,dcc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=p+dr,q+dcc
                        if 0<=x<H and 0<=y<W and g[x,y]==col and lab[x,y]==0: st.append((x,y))
                yield {'cells':comp,'color':col,'n':len(comp)}
